// <diletta-breadcrumb> — a INSTÂNCIA WEB de `design-system-breadcrumb`.
//
// Ela NÃO declara pintura própria, e isso é a spec e não economia: o `## Compõe`
// da peça lista `Text link` e `Text`, e a trilha é a fileira deles. O ancestral É
// um `<diletta-text-link>`; o segmento atual é texto. Pintar aqui de novo seria a
// trilha ter opinião sobre cor de link.
//
// No Figma o componente se chama `Breadcrumb` e é UM SEGMENTO, não a trilha —
// 16 de altura em 100% das 35 instâncias, largura de 23 a 126. A trilha é esta
// peça; o segmento é o que ela repete.
import './diletta-text-link.js';

const SEPARADOR = '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false" class="sep">' +
  '<path d="M6 3l5 5-5 5" stroke="currentColor" stroke-width="1.5" fill="none" ' +
  'stroke-linecap="round" stroke-linejoin="round"/></svg>';

class DilettaBreadcrumb extends HTMLElement {
  static observedAttributes = ['trilha', 'rotulo'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this.render();
  }

  attributeChangedCallback() {
    if (this.shadowRoot) this.render();
  }

  /// `Rótulo>/destino | Outro>/outro | Atual` — o último SEM destino é o atual.
  get niveis() {
    return (this.getAttribute('trilha') || '')
      .split('|')
      .map((s) => s.trim())
      .filter(Boolean)
      .map((s) => {
        const i = s.indexOf('>');
        return i < 0 ? { rotulo: s } : { rotulo: s.slice(0, i).trim(), href: s.slice(i + 1).trim() };
      });
  }

  render() {
    const n = this.niveis;
    const corpo = n.map((nivel, i) => {
      const atual = i === n.length - 1;
      // O ATUAL nunca é link, mesmo que venha com destino. Oferecer navegação
      // para onde já se está faz o leitor de tela anunciar um destino que não
      // existe — e a spec põe isso como requisito, não como cuidado.
      const item = atual
        ? `<span class="atual" aria-current="page">${nivel.rotulo}</span>`
        : `<diletta-text-link tone="brand" underline="onHover" href="${(nivel.href || '#').replace(/"/g, '&quot;')}">${nivel.rotulo}</diletta-text-link>`;
      // O separador é da TRILHA e sai da árvore de semântica: sem isso o leitor
      // lê "maior que" entre cada nível.
      return (i ? SEPARADOR : '') + item;
    }).join('');

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        ol { display: flex; align-items: center; gap: 6px; list-style: none; margin: 0; padding: 0; }
        .atual { color: var(--cps-fg); }
        .sep { width: 12px; height: 12px; color: var(--cps-textMuted); flex: none; }
        /* A trilha encolhe pelo MEIO: perder a raiz tira o retorno, perder o
           atual tira a resposta à pergunta que a trilha existe pra responder. */
        ol > *:not(:first-child):not(:last-child):not(.sep) {
          overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0;
        }
      </style>
      <nav aria-label="${this.getAttribute('rotulo') || 'Trilha de navegação'}">
        <ol>${corpo}</ol>
      </nav>`;
  }
}

customElements.define('diletta-breadcrumb', DilettaBreadcrumb);
export { DilettaBreadcrumb };
